<?php if($page==='catalog'):
$department=(string)($_GET['department']??'');$search=trim((string)($_GET['search']??''));$where=['p.active=1'];$params=[];
if(in_array($department,['Women','Men','Kids'],true)){$where[]='c.department=?';$params[]=$department;}
if($search!==''){$where[]='(p.name LIKE ? OR p.description LIKE ?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';}
if(!empty($_GET['category'])){$where[]='c.id=?';$params[]=(int)$_GET['category'];}
if(!empty($_GET['color'])){$where[]='EXISTS(SELECT 1 FROM variants v WHERE v.product_id=p.id AND v.color=?)';$params[]=(string)$_GET['color'];}
if(!empty($_GET['size'])){$where[]='EXISTS(SELECT 1 FROM variants v WHERE v.product_id=p.id AND v.size=? AND v.stock>0)';$params[]=(string)$_GET['size'];}
if(isset($_GET['max_price'])&&is_numeric($_GET['max_price'])){$where[]='p.price<=?';$params[]=(float)$_GET['max_price'];}
$sorts=['new'=>'p.id DESC','price_asc'=>'p.price ASC,p.id','price_desc'=>'p.price DESC,p.id','name'=>'p.name ASC,p.id'];$sort=(string)($_GET['sort']??'new');$products=all('SELECT p.*,c.department FROM products p JOIN categories c ON c.id=p.category_id WHERE '.implode(' AND ',$where).' ORDER BY '.($sorts[$sort]??$sorts['new']),$params);
?>
<section class="catalog-intro container"><p class="eyebrow">THE FORME COLLECTION</p><h1><?=e($search!==''?'Search: '.$search:($department?:'Everyday essentials.'))?></h1><p>Considered pieces. Endless possibilities.</p></section><section class="container"><form class="filters" method="get"><input type="hidden" name="page" value="catalog"><input type="hidden" name="department" value="<?=e($department)?>"><label class="search-field">Search<input name="search" placeholder="Find your next favourite" value="<?=e($search)?>"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach(all('SELECT * FROM categories ORDER BY department,name') as $c):if($department&&$c['department']!==$department)continue;?><option value="<?=$c['id']?>" <?=(string)($_GET['category']??'')===(string)$c['id']?'selected':''?>><?=e($c['department'].' / '.$c['name'])?></option><?php endforeach;?></select></label><label>Colour<select name="color"><option value="">All colours</option><?php foreach(all('SELECT DISTINCT color FROM variants ORDER BY color') as $v):?><option <?=($_GET['color']??'')===$v['color']?'selected':''?>><?=e($v['color'])?></option><?php endforeach;?></select></label><label>Size<select name="size"><option value="">All sizes</option><?php foreach(['XS','S','M','L','XL','3-4Y','5-6Y','7-8Y'] as $s):?><option <?=($_GET['size']??'')===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></label><label>Max price · RM<input type="number" min="0" step="0.01" name="max_price" value="<?=e($_GET['max_price']??'')?>" placeholder="Any"></label><label>Sort<select name="sort"><?php foreach(['new'=>'Newest first','price_asc'=>'Price: low to high','price_desc'=>'Price: high to low','name'=>'Name'] as $key=>$value):?><option value="<?=$key?>" <?=$sort===$key?'selected':''?>><?=$value?></option><?php endforeach;?></select></label><button class="btn">Apply</button></form><div class="results-line"><span><?=count($products)?> pieces</span><a href="<?=e(url('catalog',['department'=>$department]))?>">Clear filters</a></div><?php if($products):?><div class="product-grid catalog-grid"><?php foreach($products as $p)product_card($p);?></div><?php else:?><div class="empty-state"><h2>No pieces found.</h2><p>Try another search or clear your filters.</p></div><?php endif;?></section>
<?php else:
$p=one('SELECT p.*,c.name category,c.department FROM products p JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1',[(int)($_GET['id']??0)]);
if(!$p){http_response_code(404);echo '<div class="empty-state"><h1>Product unavailable.</h1><a href="index.php?page=catalog">Explore the collection</a></div>';return;}
$variants=all('SELECT * FROM variants WHERE product_id=? ORDER BY id',[$p['id']]);$images=all('SELECT * FROM product_images WHERE product_id=? ORDER BY id',[$p['id']]);$selected=$variants[0]??null;$colors=[];foreach($variants as $v)if(!isset($colors[$v['color']]))$colors[$v['color']]=$v;
?>
<div class="container breadcrumb"><a href="<?=e(url('catalog',['department'=>$p['department']]))?>"><?=e($p['department'])?></a> / <?=e($p['category'])?> / <?=e($p['name'])?></div>
<section class="container product-detail" data-product><div class="gallery" data-gallery><?php if($selected):?><img src="<?=e(safe_image($selected['image']))?>" alt="<?=e($p['name'].' — '.$selected['color'])?>" data-main-product-image><?php foreach($images as $im):?><img src="<?=e(safe_image($im['image']))?>" alt="<?=e($p['name'].' — '.$im['color'].' detail')?>" data-gallery-color="<?=e($im['color'])?>" <?=$im['color']!==$selected['color']?'hidden':''?>><?php endforeach;?><?php else:?><img src="assets/product-sage.svg" alt="Product image placeholder"><?php endif;?></div><div class="product-info"><p class="eyebrow"><?=e($p['department'].' / '.$p['category'])?></p><h1><?=e($p['name'])?></h1><p class="detail-price"><?=money($p['price'])?></p><p><?=e($p['description'])?></p>
<?php if($selected):?><form method="post" class="purchase-form"><?=token()?><input type="hidden" name="action" value="cart_add"><p>Colour: <strong data-color-name><?=e($selected['color'])?></strong></p><div class="swatches large"><?php foreach($colors as $color=>$v):?><button type="button" class="swatch <?=$color===$selected['color']?'selected':''?>" style="--swatch:<?=e($v['hex'])?>" data-product-color="<?=e($color)?>" data-image="<?=e(safe_image($v['image']))?>" aria-label="<?=e($color)?>"></button><?php endforeach;?></div><label>Size<select name="variant_id" required data-variant-select><?php foreach($variants as $v):?><option value="<?=$v['id']?>" data-color="<?=e($v['color'])?>" data-stock="<?=$v['stock']?>" <?=$v['stock']==0?'disabled':''?>><?=e($v['size'].' · '.$v['color'].($v['stock']?' · '.$v['stock'].' available':' · Sold out'))?></option><?php endforeach;?></select></label><a class="text-link" href="<?=e(url('help',['topic'=>'size']))?>">Size guide →</a><div class="purchase-row"><label>Quantity<input type="number" name="quantity" value="1" min="1" max="99" required></label><button class="btn" data-add-button>Add to bag →</button></div><p class="stock-note" data-stock-note></p></form><?php else:?><p class="notice">Coming soon. This product has no available variants.</p><?php endif;?>
<form method="post"><?=token()?><input type="hidden" name="action" value="wishlist"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-outline full">♡ Save / remove from wishlist</button></form><p class="delivery-note">Free Malaysia delivery over RM 200.<br>Standard delivery RM 8. Demo store only.</p><details open><summary>Description</summary><p><?=e($p['description'])?></p></details><details><summary>Materials & care</summary><p><?=e($p['material'])?></p></details><details><summary>Delivery & returns</summary><p>Demonstration policy: standard delivery 3–5 working days. Unworn pieces may be returned within 14 days. No real dispatch or payment occurs.</p></details></div></section>
<section class="container section reviews"><p class="eyebrow">YOUR EVERYDAY STORIES</p><h2>Reviews</h2><?php $reviews=all('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE product_id=? ORDER BY r.id DESC',[$p['id']]);if(!$reviews):?><p>No reviews yet. Reviews are available to customers with a completed order.</p><?php endif;?><?php foreach($reviews as $r):?><article class="review"><strong><?=e($r['name'])?></strong><span><?=str_repeat('★',(int)$r['rating'])?></span><p><?=e($r['comment'])?></p></article><?php endforeach;?><?php if($currentUser):?><form method="post" class="form-grid narrow"><?=token()?><input type="hidden" name="action" value="review"><input type="hidden" name="product_id" value="<?=$p['id']?>"><label>Rating<select name="rating"><?php for($i=5;$i>=1;$i--):?><option><?=$i?></option><?php endfor;?></select></label><label>Your review<textarea name="comment" maxlength="1500" required><?=old('comment')?></textarea></label><button class="btn">Save review</button></form><form method="post"><?=token()?><input type="hidden" name="action" value="review_delete"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="text-button">Delete my review</button></form><?php endif;?></section><section class="container section"><div class="section-heading"><h2>A little more your style.</h2></div><div class="product-grid"><?php foreach(all('SELECT p.*,c.department FROM products p JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND c.department=? AND p.id<>? ORDER BY (p.category_id=?) DESC,p.id DESC LIMIT 4',[$p['department'],$p['id'],$p['category_id']]) as $related)product_card($related);?></div></section>
<?php endif;?>
